const DUEL_PEERJS = ['https://cdn.jsdelivr.net/npm/peerjs@1.5.4/dist/peerjs.min.js', 'https://unpkg.com/peerjs@1.5.4/dist/peerjs.min.js', 'https://cdn.jsdelivr.net/npm/peerjs@1.5.5/dist/peerjs.min.js'];
const DUEL_STUN = [{ urls: 'stun:stun.l.google.com:19302' }, { urls: 'stun:stun1.l.google.com:19302' }, { urls: 'stun:stun2.l.google.com:19302' }, { urls: 'stun:stun3.l.google.com:19302' }, { urls: 'stun:stun.cloudflare.com:3478' }];
function duelTeam(s) { return s % 2; }
function duelRelayUrl() { try { return localStorage.getItem('tankers_relay') || ''; } catch (e) { return ''; } }
function duelIce(cb) { const u = duelRelayUrl(); if (!u) { cb(DUEL_STUN); return; } duelStatus('Loading your relay…'); fetch(u).then(function (r) { return r.json(); }).then(function (list) { cb(DUEL_STUN.concat(Array.isArray(list) ? list : (list.iceServers || []))); }).catch(function () { duelStatus('Could not load the relay link — trying without it.', true); cb(DUEL_STUN); }); }
function duelPeerOpts(ice) { return { config: { iceServers: ice, iceTransportPolicy: 'all' }, debug: 1 }; }
function duelSaveRelay() { const v = (document.getElementById('duelRelayIn') || {}).value || ''; try { if (v.trim()) localStorage.setItem('tankers_relay', v.trim()); else localStorage.removeItem('tankers_relay'); } catch (e) {} duelStatus(v.trim() ? 'Relay saved. Host or join again.' : 'Relay removed.'); }
// guest: watch the WebRTC handshake and fall back to the relay if it gets stuck
function duelWatch(c) { if (c.relay || DUEL.role !== 'guest') return; const t0 = Date.now(); const iv = setInterval(function () { if (DUEL.conn !== c) { clearInterval(iv); return; } if (c.open) { clearInterval(iv); return; } const pc = c.peerConnection, st = pc ? pc.iceConnectionState : 'waiting'; const secs = Math.round((Date.now() - t0) / 1000);
        if (st === 'failed' || secs > 10) { clearInterval(iv); try { c.close(); } catch (e) {} DUEL.conn = null; duelRelayJoin(DUEL.code); return; }
        duelStatus('Host found! ' + (st === 'checking' || st === 'waiting' || st === 'new' ? 'Finding a route between your networks… ' : 'Linking up (' + st + ')… ') + secs + 's'); }, 500); }
/* ---------- backup route: a free public message relay (MQTT over secure websockets). No sign-up, no card. ---------- */
const DUEL_MQTT_LIB = ['https://cdn.jsdelivr.net/npm/mqtt@5.10.1/dist/mqtt.min.js', 'https://unpkg.com/mqtt@5.10.1/dist/mqtt.min.js', 'https://cdn.jsdelivr.net/npm/mqtt@4.3.7/dist/mqtt.min.js'];
const DUEL_BROKERS = ['wss://broker.emqx.io:8084/mqtt', 'wss://broker.hivemq.com:8884/mqtt', 'wss://test.mosquitto.org:8081'];
function duelLoadMqtt(cb) { if (window.mqtt && window.mqtt.connect) { cb(true); return; } let i = 0; const next = function () { if (i >= DUEL_MQTT_LIB.length) { cb(false); return; } const s = document.createElement('script'); s.src = DUEL_MQTT_LIB[i++]; s.onload = function () { if (window.mqtt && window.mqtt.connect) cb(true); else next(); }; s.onerror = next; document.head.appendChild(s); }; next(); }
function duelTopic(code, dir) { return 'tankers-duel/v2/' + duelNorm(code).toLowerCase() + '/' + dir; }
function duelRelayConn(client, out, gid) { const c = { open: false, relay: true, gid: gid, h: {}, on: function (e, f) { (c.h[e] = c.h[e] || []).push(f); }, emit: function (e, a) { (c.h[e] || []).forEach(function (f) { f(a); }); },
    send: function (m) { try { if (gid && DUEL.role === 'guest') m = Object.assign({ gid: gid }, m); client.publish(out, JSON.stringify(m), { qos: 0 }); } catch (e) {} }, close: function () { if (c.open) c.send({ t: 'bye' }); c.open = false; if (DUEL.role === 'guest') try { setTimeout(function () { client.end(true); }, 150); } catch (e) {} } }; return c; }
function duelMqtt(url, onUp, onFail) { let done = false; try { const cl = window.mqtt.connect(url, { clientId: 'tankers_' + Math.random().toString(36).slice(2, 10), clean: true, connectTimeout: 6000, reconnectPeriod: 0, keepalive: 30 });
    cl.on('connect', function () { if (!done) { done = true; onUp(cl); } }); cl.on('error', function () { if (!done) { done = true; try { cl.end(true); } catch (e) {} onFail(); } }); setTimeout(function () { if (!done) { done = true; try { cl.end(true); } catch (e) {} onFail(); } }, 7000); } catch (e) { if (!done) { done = true; onFail(); } } }
// host: listen for relay callers on every broker we can reach; each guest has its own reply topic
function duelRelayHost(code) { duelLoadMqtt(function (ok) { if (!ok || DUEL.role !== 'host' || DUEL.code !== code) return; DUEL.relays = DUEL.relays || []; DUEL.rconns = DUEL.rconns || {};
    DUEL_BROKERS.forEach(function (url) { duelMqtt(url, function (cl) { if (DUEL.role !== 'host' || DUEL.code !== code) { try { cl.end(true); } catch (e) {} return; } DUEL.relays.push(cl); const inT = duelTopic(code, 'g2h'); cl.subscribe(inT);
        cl.on('message', function (topic, buf) { if (topic !== inT) return; let m; try { m = JSON.parse(buf.toString()); } catch (e) { return; } const g = m.gid; if (!g) return; const ex = DUEL.rconns[g];
            if (ex) { if (ex.client !== cl) return; if (m.t === 'bye') ex.emit('close'); else ex.emit('data', m); return; }
            if (m.t === 'hello') { const c = duelRelayConn(cl, duelTopic(code, 'h2g-' + g), g); c.client = cl; DUEL.rconns[g] = c; duelBind(c); c.open = true; c.emit('open'); c.emit('data', m); } }); }, function () {}); }); }); }
// guest: call through the first broker that answers, and wait for the host's reply
function duelRelayJoin(code) { if (DUEL.relayTried) return; DUEL.relayTried = true; duelStatus('Direct link blocked — switching to the backup relay…'); duelLoadMqtt(function (ok) { if (!ok) { duelStatus('Could not reach the backup relay either. Check your internet connection.', true); duelJoinReset(); return; } let k = 0;
    const tryB = function () { if (DUEL.role !== 'guest' || DUEL.code !== code || (DUEL.conn && DUEL.conn.open)) return; if (k >= DUEL_BROKERS.length) { duelStatus('No answer from ' + code + '. Check the code, and that your friend is still on the HOST screen with DUEL VERSION ' + DUEL_BUILD + ' at the top (if not, they need to refresh with Ctrl+F5).', true); duelJoinReset(); return; }
        duelMqtt(DUEL_BROKERS[k++], function (cl) { if (DUEL.conn && DUEL.conn.open) { try { cl.end(true); } catch (e) {} return; } DUEL.relays = (DUEL.relays || []).concat([cl]); const inT = duelTopic(code, 'h2g-' + DUEL.gid), outT = duelTopic(code, 'g2h'), c = duelRelayConn(cl, outT, DUEL.gid); c.client = cl; let answered = false;
            cl.subscribe(inT, function () { c.send({ t: 'hello', tank: DUEL.tank }); duelStatus('Calling ' + code + ' through the backup relay…'); });
            cl.on('message', function (topic, buf) { if (topic !== inT) return; let m; try { m = JSON.parse(buf.toString()); } catch (e) { return; } if (!answered) { if (DUEL.conn && DUEL.conn.open) return; answered = true; duelBind(c); c.open = true; } if (m.t === 'bye') c.emit('close'); else c.emit('data', m); });
            setTimeout(function () { if (!answered && DUEL.role === 'guest' && DUEL.code === code && !(DUEL.conn && DUEL.conn.open)) { try { cl.end(true); } catch (e) {} tryB(); } }, 8000); }, tryB); }; tryB(); }); }
function duelJoinReset() { const b = document.getElementById('duelJoinBtn'); if (b) b.disabled = false; }
function duelCode() { return DUEL_WORDS[Math.floor(Math.random() * DUEL_WORDS.length)] + '-' + (1000 + Math.floor(Math.random() * 9000)); }
function duelNorm(c) { return String(c || '').toUpperCase().replace(/[^A-Z0-9]+/g, '-').replace(/^-+|-+$/g, ''); }
function duelPeerId(code) { return 'tankers-duel-' + duelNorm(code).toLowerCase(); }
function duelLink(code) { return location.href.split('#')[0].split('?')[0] + '?duel=' + code; }
function duelLoadPeer(cb, fail) { if (window.Peer) { cb(); return; } let i = 0; const next = function () { if (i >= DUEL_PEERJS.length) { if (fail) fail(); else duelStatus('Could not load the online radio (PeerJS). Check your internet connection and try again.', true); return; } const s = document.createElement('script'); s.src = DUEL_PEERJS[i++]; s.onload = function () { if (window.Peer) cb(); else next(); }; s.onerror = next; document.head.appendChild(s); }; next(); }
